def is_square_of_rational(x):
    """Checks if a positive rational number x is the square of a rational number."""
    if x <= 0:
        return False

    # Convert to fraction
    from fractions import Fraction
    f = Fraction(x)

    numerator = f.numerator
    denominator = f.denominator

    # Check if numerator and denominator are perfect squares
    def is_perfect_square(n):
        if n < 0:
            return False
        if n == 0:
            return True
        # Check using integer square root
        s = int(n**0.5)
        return s*s == n

    return is_perfect_square(numerator) and is_perfect_square(denominator)

